template:
{%- set publisher = "studio-publish" in scope -%}
<div class="studio-field studio-field-prefix">
{%- if publisher -%}
<label class="studio-field-label" for="{{ input_id }}">Prefix</label><input id="{{ input_id }}" class="studio-field-input" type="text" name="{{ pointer }}" value="{{ value }}" placeholder="/segment/" spellcheck="false" autocomplete="off"{% if errors %} aria-invalid="true" aria-describedby="{{ input_id }}-errors"{% endif %}>
{%- else -%}
<span class="studio-field-label">Prefix</span> <span data-studio-branch-prefix-text>{{ value }}</span>
{%- endif -%}
{%- if errors %}<ul class="scrud-errors studio-field-errors" id="{{ input_id }}-errors" role="alert">{% for error in errors %}<li>{{ error }}</li>{% endfor %}</ul>{% endif -%}
</div>
